source('mp10_hypothesis_followup_v1/scripts/common.R');suppressPackageStartupMessages(library(fgsea))
z<-old('gsea_results.tsv.gz');plan<-old('model_plan.tsv');bad<-unique(z[!is.finite(pval)|(!is.finite(log2err)&pval>1e-10),.(model_id,library,mask)]);dir.create(file.path(B,'tables/gsea_repair'),showWarnings=FALSE);out<-list();logs<-list()
for(i in seq_len(nrow(bad))){r<-bad[i];de<-old(paste0('de/',r$model_id,'.tsv.gz'));de[,stat:=sign(logFC)*sqrt(pmax(F,0))];de<-de[is.finite(stat)];if(r$mask=='M20-masked')de<-de[!gene%in%M20];setorder(de,-stat,gene);v<-setNames(de$stat,de$gene);gs<-fread(file.path(REF,if(r$library=='Hallmark')'hallmark.tsv.gz'else'reactome.tsv.gz'));pw<-lapply(split(gs$gene_symbol,gs$gs_name),unique);if(r$mask=='M20-masked')pw<-lapply(pw,setdiff,y=M20)
 sig<-digest(list(v,pw,r,10000,100000,123,'fgsea1.36.2',15,500,1e-10),algo='sha256');f<-file.path(B,'tables/gsea_repair',paste0(paste(r,collapse='_'),'.tsv.gz'))
 if(file.exists(f)&&file.exists(paste0(f,'.sha256'))&&readLines(paste0(f,'.sha256'))==sig){rr<-fread(f)}else{
  for(budget in c(10000,100000)){warn<-character();set.seed(123);rr<-withCallingHandlers(as.data.table(fgseaMultilevel(pw,v,minSize=15,maxSize=500,nPermSimple=budget,eps=1e-10,nproc=1,scoreType='std')),warning=function(w){warn<<-c(warn,conditionMessage(w));invokeRestart('muffleWarning')});rr[,nPermSimple:=budget];logs[[paste(i,budget)]]<-data.table(model_id=r$model_id,library=r$library,mask=r$mask,budget=budget,warning=paste(unique(warn),collapse=' | '),unresolved=sum(!is.finite(rr$pval)|(!is.finite(rr$log2err)&rr$pval>1e-10)));cat('REPAIR',i,nrow(bad),r$model_id,r$library,r$mask,budget,'NA',sum(!is.finite(rr$pval)),'\n');put(rbindlist(logs,fill=TRUE),'gsea_repair_warnings.tsv');if(!any(!is.finite(rr$pval)|(!is.finite(rr$log2err)&rr$pval>1e-10)))break}
  rr[,leadingEdge:=vapply(leadingEdge,paste,collapse=';',FUN.VALUE=character(1))];rr[,`:=`(model_id=r$model_id,library=r$library,mask=r$mask,db_version=paste(unique(gs$db_version),collapse=';'))];fwrite(rr,f,sep='\t',compress='gzip');writeLines(sig,paste0(f,'.sha256'))
 };out[[i]]<-rr
}
new<-rbindlist(out,fill=TRUE);keys<-c('model_id','library','mask','pathway');comparison<-merge(z,new,by=keys,suffixes=c('_old','_repaired'));put(comparison,'gsea_numeric_repair_comparison.tsv.gz');z[,recomputed:=FALSE];zz<-z[!unique(new[,.(model_id,library,mask)]),on=.(model_id,library,mask)];new[,recomputed:=TRUE];z<-rbindlist(list(zz,new),fill=TRUE);z[,padj:=p.adjust(pval,'BH'),by=.(model_id,library,mask)];z[,joint_main_q:=NA_real_];for(lib in unique(z$library))for(k in c('Epi','receiver')){ix<-which(z$library==lib&z$mask=='Full'&z$model_id%in%plan[primary&kind==k,model_id]);z[ix,joint_main_q:=p.adjust(pval,'BH')]};put(z,'gsea_results_repaired.tsv.gz');cat('GSEA REPAIR COMPLETE\n')
